import {test,expect} from "bun:test";
import {readFileSync,writeFileSync,mkdirSync,mkdtempSync} from "node:fs";
import {join} from "node:path";
import {createRequire} from "node:module";
import Ajv from "ajv";
import {selectedCargoArguments,cargoOwnerPreparations,type CargoArgumentScope} from "../../🟦️.ts";
import {runCargoProbe} from "../../../../🧪️tests/🎛️cargo-owner/🟦️.ts";
const corpus=JSON.parse(readFileSync(new URL("../🧫️scope/🔣️.json",import.meta.url),"utf8")),schema=JSON.parse(readFileSync(new URL("../🧬️scope/🔣️.json",import.meta.url),"utf8")),output=process.env.SEMIO_TEST_ARTIFACT_DIR;
if(!output)throw Error("Caller-owned scope test output is required");
const put=(root:string,path:string,source:string)=>{mkdirSync(join(root,path,".."),{recursive:true});writeFileSync(join(root,path),source);};
const workspace=(members:string[])=>`[workspace]\nresolver="2"\nmembers=${JSON.stringify(members)}\n[workspace.metadata.semio.repository]\nschema-version=1\nexclude-patterns=[]\nowner-manifests=["unrelated/Cargo.toml"]\nmember-manifests=${JSON.stringify(members.map(path=>path+"/Cargo.toml"))}\n`;
const packageText='[package]\nname="core-one"\nversion="0.1.0"\nedition="2021"\n[lib]\npath="🦀️.rs"\n';
test("variable argument scope matches strict independent schema without source fallback",async()=>{const validate=new Ajv({strict:true}).compile(schema);for(const row of corpus.requests){expect(validate(row.scope),row.id).toBe(row.accepted);if(row.accepted)expect(await runCargoProbe(output!,owner=>selectedCargoArguments(output!,["--version"],row.scope as CargoArgumentScope,owner.operation))).toEqual(["--version"]);else await expect(runCargoProbe(output!,owner=>selectedCargoArguments(output!,["--version"],row.scope as CargoArgumentScope,owner.operation))).rejects.toThrow();}});
test("selected arguments admit only their actual manifest scope while unrelated owners remain unread",async()=>{for(const row of corpus.selection){const root=mkdtempSync(join(output!,"scoped-arguments-"));put(root,"Cargo.toml",workspace(row.members));put(root,"packages/core/Cargo.toml",packageText);put(root,"packages/core/🦀️.rs","pub fn core(){}\n");put(root,"unrelated/Cargo.toml","unclosed=[");if(row.malformedSibling)put(root,"packages/broken/Cargo.toml","unclosed=[");const oracle=Bun.spawnSync(["node","--eval",`const t=require(${JSON.stringify(createRequire(import.meta.url).resolve("@iarna/toml"))});const fs=require('node:fs');const p=t.parse(fs.readFileSync(process.argv[1],'utf8'));console.log(JSON.stringify({name:p.package.name,version:p.package.version}));`,join(root,"packages/core/Cargo.toml")]);expect(oracle.exitCode).toBe(0);expect(JSON.parse(oracle.stdout.toString())).toEqual({name:"core-one",version:"0.1.0"});if(row.manifest)expect(await runCargoProbe(root,owner=>selectedCargoArguments(root,row.args,row.scope,owner.operation))).toEqual([row.args[0],"--manifest-path",join(root,row.manifest),...row.args.slice(1)]);else await expect(runCargoProbe(root,owner=>selectedCargoArguments(root,row.args,row.scope,owner.operation))).rejects.toThrow(/scope/);}});
test("selected leaf preparation does not enumerate a malformed sibling member",async()=>{const root=mkdtempSync(join(output!,"scoped-preparation-"));put(root,"Cargo.toml",workspace(["packages/core","packages/broken"]));put(root,"packages/core/Cargo.toml",packageText);put(root,"packages/broken/Cargo.toml","unclosed=[");put(root,"unrelated/Cargo.toml","unclosed=[");expect(await runCargoProbe(root,owner=>cargoOwnerPreparations(root,{schemaVersion:1,manifest:"packages/core/Cargo.toml",packages:["core-one"]},owner.operation))).toEqual([]);});

